print("load err:", err)
var ms = cf.get_value("application", "config/main_scene")
print("main_scene value: ", ms)
print("all sections: ", cf.get_sections())
for s in cf.get_sections():
    for k in cf.get_section_keys(s):
        print(" %s.%s = %s" % [s, k, cf.get_value(s, k)])

extends SceneTree

func _init():
    var cf = ConfigFile.new()
    var err = cf.load("project.godot")
    print("load err:", err)
    var ms = cf.get_value("application", "config/main_scene")
    print("main_scene value: ", ms)
    print("all sections: ", cf.get_sections())
    for s in cf.get_sections():
        for k in cf.get_section_keys(s):
            print(" %s.%s = %s" % [s, k, cf.get_value(s, k)])
    quit()

